{
  "status": "SUPPORTED",
  "task_summary": "Identify components, fasten target, place tool.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "fastening_target",
        "entity_kind": "OBJECT",
        "function": "The specific location or assembly requiring a fastener to be attached.",
        "required_count": 1,
        "binding_policy": "DISTINCT"
      ,
        "candidate_categories": ["assembly", "part", "fixture"],
        "required_properties": ["needs fastening"]
      },
      {
        "id": "fastening_component",
        "entity_kind": "OBJECT",
        "function": "The hardware item (screw, bolt, etc.) needed to secure the target.",
        "required_count": 1,
        "binding_policy": "DISTINCT"
      ,
        "candidate_categories": ["screw", "bolt", "nut", "pin"],
        "required_properties": ["compatible with fastening target"]
      },
      {
        "id": "fastening_tool",
        "entity_kind": "OBJECT",
        "function": "The implement used to apply the fastening component.",
        "required_count": 1,
        "binding_policy": "REUSABLE"
      ,
        "candidate_categories": ["screwdriver", "wrench", "drill", "pliers"],
        "required_properties": ["capable of driving fastening component"]
      },
      {
        "id": "workbench",
        "entity_kind": "REGION",
        "function": "The surface where the task occurs and where tools must be left.",
        "required_count": 1,
        "binding_policy": "SHARED"
      ,
        "candidate_categories": ["table", "desk", "bench"],
        "required_properties": ["flat surface", "holds items"]
      }
    ],
    "functional_relations": [
      {
        "id": "component_suits_target",
        "relation": "SUITABILITY",
        "participant_roles": ["fastening_component", "fastening_target"],
        "required": true
      },
      {
        "id": "tool_applies_fastening",
        "relation": "DEPENDENCE",
        "participant_roles": ["fastening_tool", "fastening_component", "fastening_target"],
        "required": true
      },
      {
        "id": "tool_ended_on_bench",
        "relation": "LOCATION",
        "participant_roles": ["fastening_tool", "workbench"],
        "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "locate_component",
        "operation": "SEARCH",
        "participant_roles": ["fastening_component", "fastening_tool"],
        "operation_count": 1
      },
      {
        "id": "execute_fastening",
        "operation": "MANIPULATION",
        "participant_roles": ["fastening_tool", "fastening_component", "fastening_target"],
        "operation_count": 1
      },
      {
        "id": "deposit_tool",
        "operation": "PLACE",
        "participant_roles": ["fastening_tool", "workbench"],
        "operation_count": 1
      }
    ]
  },
  "observation_guidance": {
    "visible_candidates_per_role": {
      "fastening_target": [
        {
          "label": "tray on workbench",
          "visual_description": "Black tray containing yellow and blue objects."
        }
      ],
      "fastening_component": [
        {
          "label": "tray contents",
          "visual_description": "Yellow rectangular and blue cylindrical items in the tray."
        }
      ],
      "fastening_tool": []
    },
    "inspectable_regions": [
      {
        "id": "left_drawer",
        "label": "Left Drawer",
        "visual_description": "Blue drawer with white handle under the workbench.",
        "reason": "Closed storage structure potentially holding tools or components."
      },
      {
        "id": "right_drawer",
        "label": "Right Drawer",
        "visual_description": "Blue drawer with white handle under the workbench.",
        "reason": "Closed storage structure potentially holding tools or components."
      },
      {
        "id": "cabinet",
        "label": "Cabinet",
        "visual_description": "Tall blue cabinet with a door behind the workbench.",
        "reason": "Closed storage structure potentially holding tools or components."
      }
    ],
    "inspection_order": [
      "left_drawer",
      "right_drawer",
      "cabinet"
    ]
  }
  ,
  "unsupported_reason": ""
  ,
  "schema_version": 3
}
